struct Empty {};
struct Modern {
    int i;
    [[no_unique_address]] Empty e;     // 0 bytes, no inherited names
};
static_assert(sizeof(Modern) == sizeof(int));

template <class Policy, class T>
struct compressed_pair : private Policy {
    T second;
    T&      get()    { return second; }
    Policy& policy() { return *this; }   // empty base: 0 bytes
};
static_assert(sizeof(compressed_pair<Empty, int>) == sizeof(int));
